<span class="line"><span style="color:#C678DD;">catch</span><span style="color:#ABB2BF;"> (</span><span style="color:#E5C07B;">HttpRequestException</span><span style="color:#E06C75;"> ex</span><span style="color:#ABB2BF;">)</span></span>
