<span class="line"><span style="color:#C678DD;">    private</span><span style="color:#C678DD;"> readonly</span><span style="color:#E5C07B;"> ILogger</span><span style="color:#E06C75;"> _logger</span><span style="color:#ABB2BF;">;</span></span>
