<span class="line"><span style="color:#C678DD;">    public</span><span style="color:#C678DD;"> async</span><span style="color:#E5C07B;"> Task</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#E5C07B;">Result</span><span style="color:#ABB2BF;">&gt; </span><span style="color:#61AFEF;">ProcessAsync</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">Request</span><span style="color:#E5C07B;"> request</span><span style="color:#ABB2BF;">)</span></span>
